17	// Client is a persistent connection to the cmux Unix socket.
18	// It serialises all sends with a mutex so callers can share one instance.
19	type Client struct {
20		socketPath string
21		password   string
22	
23		mu     sync.Mutex
24		conn   net.Conn
25		reader *bufio.Reader
26	}
