32	// Connect establishes (or re-establishes) the connection and authenticates.
33	func (c *Client) Connect() error {
34		c.mu.Lock()
35		defer c.mu.Unlock()
36	
37		if c.conn != nil {
38			c.conn.Close()
39			c.conn = nil
40			c.reader = nil
41		}
42	
43		conn, err := net.Dial("unix", c.socketPath)
44		if err != nil {
45			return fmt.Errorf("connect %s: %w", c.socketPath, err)
46		}
47	
48		if c.password != "" {
49			if err := authenticate(conn, c.password); err != nil {
50				conn.Close()
51				return fmt.Errorf("auth: %w", err)
52			}
53		}
54	
55		c.conn = conn
56		c.reader = bufio.NewReaderSize(conn, 1<<20)
57		return nil
58	}
