70	// Send sends a v2 JSON-RPC request and returns the parsed result object.
71	// If the connection is closed it returns an error; the caller is responsible
72	// for reconnecting.
73	func (c *Client) Send(method string, params map[string]any) (json.RawMessage, error) {
74		c.mu.Lock()
75		defer c.mu.Unlock()
76	
77		if c.conn == nil {
78			return nil, fmt.Errorf("not connected")
79		}
80	
81		id := randomHex(8)
82		req := map[string]any{
83			"id":     id,
84			"method": method,
85			"params": params,
86		}
87		if params == nil {
88			req["params"] = map[string]any{}
89		}
90	
91		payload, err := json.Marshal(req)
92		if err != nil {
93			return nil, fmt.Errorf("marshal: %w", err)
94		}
95	
96		_ = c.conn.SetDeadline(time.Now().Add(10 * time.Second))
97		if _, err := fmt.Fprintf(c.conn, "%s\n", payload); err != nil {
98			c.conn = nil
99			c.reader = nil
100			return nil, fmt.Errorf("write: %w", err)
101		}
102	
103		line, err := c.reader.ReadString('\n')
104		if err != nil {
105			c.conn = nil
106			c.reader = nil
107			return nil, fmt.Errorf("read: %w", err)
108		}
109		if len(line) > 8<<20 {
110			c.conn = nil
111			c.reader = nil
112			return nil, fmt.Errorf("response line too large: %d bytes", len(line))
113		}
114		_ = c.conn.SetDeadline(time.Time{})
115	
116		var resp struct {
117			OK     bool            `json:"ok"`
118			Result json.RawMessage `json:"result"`
119			Error  *struct {
120				Code    string `json:"code"`
121				Message string `json:"message"`
122			} `json:"error"`
123		}
124		if err := json.Unmarshal([]byte(strings.TrimSpace(line)), &resp); err != nil {
125			return nil, fmt.Errorf("parse response: %w", err)
126		}
127		if !resp.OK {
128			if resp.Error != nil {
129				return nil, fmt.Errorf("[%s] %s", resp.Error.Code, resp.Error.Message)
130			}
131			return nil, fmt.Errorf("server returned error")
132		}
133		return resp.Result, nil
134	}
