136	// DetectSocketPath returns the best available cmux socket path by reading the
137	// last-socket-path pointer file written by the cmux Mac app, with fallbacks.
138	//
139	// cmux may write the pointer file (and the socket itself) under either the XDG
140	// state directory (cmux v2+) or the legacy Application Support directory, and
141	// may name the socket with a uid suffix (cmux-<uid>.sock) or without it
142	// (cmux.sock). We probe all known locations so a socket that exists under any
143	// of them is found instead of falling through to the legacy /tmp default.
144	func DetectSocketPath() string {
145		home, err := os.UserHomeDir()
146		if err != nil {
147			return "/tmp/cmux.sock"
148		}
149		return detectSocketPath(home, os.Getuid())
150	}
151	
152	// detectSocketPath is the pure core of DetectSocketPath, parameterised on home
153	// and uid so it can be tested against a temporary directory tree. It reads only
154	// the filesystem (via os.ReadFile/os.Stat) and returns the resolved socket path.
155	func detectSocketPath(home string, uid int) string {
156		appSupport := filepath.Join(home, "Library", "Application Support", "cmux")
157		xdgState := filepath.Join(home, ".local", "state", "cmux")
158	
159		// Primary: the last-socket-path pointer cmux writes on each launch. It can
160		// live in either the XDG state dir or Application Support; prefer a pointer
161		// whose socket actually exists, but remember the first non-empty one as a
162		// fallback in case none of the referenced sockets stat cleanly.
163		var firstPointer string
164		for _, pointer := range []string{
165			filepath.Join(xdgState, "last-socket-path"),
166			filepath.Join(appSupport, "last-socket-path"),
167		} {
168			data, err := os.ReadFile(pointer)
169			if err != nil {
170				continue
171			}
172			p := strings.TrimSpace(string(data))
173			if p == "" {
174				continue
175			}
176			if firstPointer == "" {
177				firstPointer = p
178			}
179			if _, err := os.Stat(p); err == nil {
180				return p
181			}
182		}
183	
184		// Secondary: probe known socket locations directly, covering both the
185		// uid-suffixed and plain socket names in each directory.
186		for _, candidate := range []string{
187			filepath.Join(xdgState, fmt.Sprintf("cmux-%d.sock", uid)),
188			filepath.Join(xdgState, "cmux.sock"),
189			filepath.Join(appSupport, "cmux.sock"),
190		} {
191			if _, err := os.Stat(candidate); err == nil {
192				return candidate
193			}
194		}
195	
196		// A pointer file named a socket that isn't currently present: still prefer
197		// it over the hard-coded default (the socket may appear once cmux is ready).
198		if firstPointer != "" {
199			return firstPointer
200		}
201	
202		// Legacy fallback
203		return "/tmp/cmux.sock"
204	}
