31	// Poller polls notification.list on an interval and broadcasts new events.
32	type Poller struct {
33		client   *socket.Client
34		interval time.Duration
35	
36		mu          sync.Mutex
37		subscribers []chan Event
38		seenIDs     map[string]struct{}
39		// Bumped by ResetSeenIDs. A poll captures it before its network call and
40		// discards its result if it changed meanwhile, so a notification.list issued
41		// before a clear can't repopulate seenIDs with pre-clear IDs afterward.
42		generation uint64
43	}
44	
45	func New(client *socket.Client, interval time.Duration) *Poller {
46		return &Poller{
47			client:   client,
48			interval: interval,
49			seenIDs:  make(map[string]struct{}),
50		}
51	}
52	
53	// Subscribe returns a buffered channel that receives events.
54	// Slow consumers drop events rather than blocking the poller.
55	func (p *Poller) Subscribe() <-chan Event {
56		ch := make(chan Event, 32)
57		p.mu.Lock()
58		p.subscribers = append(p.subscribers, ch)
59		p.mu.Unlock()
60		return ch
61	}
62	
63	// Unsubscribe removes a subscriber. The channel is NOT closed — closing a
64	// channel that the poller might concurrently be sending to causes a panic.
65	// The WS handler detects disconnection via other signals (ctx, incoming closed).
66	func (p *Poller) Unsubscribe(ch <-chan Event) {
67		p.mu.Lock()
68		defer p.mu.Unlock()
69		for i, sub := range p.subscribers {
70			if sub == ch {
71				p.subscribers = append(p.subscribers[:i], p.subscribers[i+1:]...)
72				return
73			}
74		}
75	}
76	
77	// Broadcast sends an event to all current subscribers directly.
78	// Used to push cmux connection state changes.
79	func (p *Poller) Broadcast(ev Event) {
80		p.mu.Lock()
81		subs := make([]chan Event, len(p.subscribers))
82		copy(subs, p.subscribers)
83		p.mu.Unlock()
84	
85		for _, sub := range subs {
86			select {
87			case sub <- ev:
88			default:
89				// slow consumer; drop
90			}
91		}
92	}
