94	// Run starts the polling loop. It blocks until stop is closed.
95	func (p *Poller) Run(stop <-chan struct{}) {
96		ticker := time.NewTicker(p.interval)
97		defer ticker.Stop()
98	
99		for {
100			select {
101			case <-stop:
102				return
103			case <-ticker.C:
104				p.poll()
105			}
106		}
107	}
