109	func (p *Poller) poll() {
110		// Capture the generation before the network call; if a clear lands while
111		// we're waiting on cmux, ingest() will discard this now-stale result.
112		p.mu.Lock()
113		gen := p.generation
114		p.mu.Unlock()
115	
116		result, err := p.client.Send("notification.list", nil)
117		if err != nil {
118			log.Printf("poller: notification.list error: %v", err)
119			return
120		}
121	
122		var payload struct {
123			Notifications []Notification `json:"notifications"`
124		}
125		if err := json.Unmarshal(result, &payload); err != nil {
126			log.Printf("poller: parse error: %v", err)
127			return
128		}
129	
130		newOnes, subs := p.ingest(payload.Notifications, gen)
131		for _, n := range newOnes {
132			ev := Event{Type: "notification.created", Data: n}
133			for _, sub := range subs {
134				select {
135				case sub <- ev:
136				default:
137					// slow consumer; drop
138				}
139			}
140		}
141	}
142	
143	// ingest records unseen notifications and returns the new ones plus a snapshot
144	// of subscribers to deliver to. If the generation changed since the poll began
145	// (a notification.clear happened mid-flight), the whole batch is discarded so
146	// stale IDs don't get re-marked as seen.
147	func (p *Poller) ingest(notifs []Notification, gen uint64) ([]Notification, []chan Event) {
148		p.mu.Lock()
149		defer p.mu.Unlock()
150		if p.generation != gen {
151			return nil, nil
152		}
153		var newOnes []Notification
154		for _, n := range notifs {
155			if _, seen := p.seenIDs[n.ID]; !seen {
156				p.seenIDs[n.ID] = struct{}{}
157				newOnes = append(newOnes, n)
158			}
159		}
160		subs := make([]chan Event, len(p.subscribers))
161		copy(subs, p.subscribers)
162		return newOnes, subs
163	}
