165	// ResetSeenIDs clears the seen-ID set. Called after notification.clear so that
166	// notifications which reappear after a clear ARE emitted again. Bumping the
167	// generation also invalidates any notification.list poll already in flight.
168	func (p *Poller) ResetSeenIDs() {
169		p.mu.Lock()
170		p.seenIDs = make(map[string]struct{})
171		p.generation++
172		p.mu.Unlock()
173	}
