40	// handleClient manages a single WebSocket connection for its lifetime.
41	// It pushes notification events and proxies commands to the cmux socket.
42	func handleClient(
43		w http.ResponseWriter,
44		r *http.Request,
45		token string,
46		poll *poller.Poller,
47		cmuxClient *socket.Client,
48		cmuxConnected func() bool,
49		resolver *claude.Resolver,
50	) {
51		if !validateBearer(r, token) {
52			http.Error(w, "Unauthorized", http.StatusUnauthorized)
53			return
54		}
55	
56		conn, err := websocket.Accept(w, r, &websocket.AcceptOptions{
57			InsecureSkipVerify: true, // LAN only; origins vary
58		})
59		if err != nil {
60			log.Printf("ws: accept error: %v", err)
61			return
62		}
63		defer conn.Close(websocket.StatusNormalClosure, "")
64	
65		ctx := r.Context()
66	
67		// Send initial connected event
68		_ = wsjson.Write(ctx, conn, pushMessage{
69			Type: "connected",
70			Data: map[string]any{
71				"bridge_version":   bridgeVersion,
72				"cmux_connected":   cmuxConnected(),
73				"protocol_version": 1,
74			},
75		})
76	
77		// Subscribe to poller events. The channel is never closed by Unsubscribe —
78		// the handler exits via ctx cancellation or incoming closing.
79		events := poll.Subscribe()
80		defer poll.Unsubscribe(events)
81	
82		// Channel for incoming commands from the client
83		incoming := make(chan commandRequest, 8)
84	
85		// Read loop: decode incoming commands and forward to incoming channel
86		go func() {
87			defer close(incoming)
88			for {
89				var cmd commandRequest
90				if err := wsjson.Read(ctx, conn, &cmd); err != nil {
91					return
92				}
93				select {
94				case incoming <- cmd:
95				case <-ctx.Done():
96					return
97				}
98			}
99		}()
100	
101		for {
102			select {
103			case <-ctx.Done():
104				return
105	
106			case ev := <-events:
107				if err := wsjson.Write(ctx, conn, pushMessage{
108					Type: ev.Type,
109					Data: ev.Data,
110				}); err != nil {
111					return
112				}
113	
114			case cmd, ok := <-incoming:
115				if !ok {
116					return
117				}
118				var resp commandResponse
119				if cmd.Method == "claude.transcript" {
120					resp = handleClaudeTranscript(cmd, cmuxClient, resolver)
121				} else {
122					resp = proxyCommand(cmd, cmuxClient, poll)
123				}
124				if err := wsjson.Write(ctx, conn, resp); err != nil {
125					return
126				}
127			}
128		}
129	}
