131	func handleClaudeTranscript(cmd commandRequest, client *socket.Client, resolver *claude.Resolver) commandResponse {
132		surfaceID, _ := cmd.Params["surface_id"].(string)
133	
134		// Build surface.list params, forwarding workspace_id if provided.
135		listParams := map[string]any{}
136		if wsID, ok := cmd.Params["workspace_id"]; ok {
137			listParams["workspace_id"] = wsID
138		}
139	
140		listResult, err := client.Send("surface.list", listParams)
141		if err != nil {
