155		if err := json.Unmarshal(listResult, &listPayload); err != nil {
156			return commandResponse{
157				ID: cmd.ID,
158				OK: false,
159				Error: &rpcError{
160					Code:    "transcript_error",
161					Message: "parse surface.list: " + err.Error(),
162				},
163			}
164		}
