166		var resumeBinding map[string]any
167		for _, s := range listPayload.Surfaces {
168			if id, _ := s["id"].(string); id == surfaceID {
169				resumeBinding, _ = s["resume_binding"].(map[string]any)
170				break
171			}
172		}
